mqd_t mqdes;
struct sigevent sev;
int status;

// 1. Setup notification delivery via signal
sev.sigev_notify = SIGEV_SIGNAL;
sev.sigev_signo  = SIGUSR1;
sev.sigev_value.sival_ptr = NULL;

// 2. Register for notification when queue transitions from empty
status = mq_notify(mqdes, &sev);

// 3. Unregister existing notification handler
status = mq_notify(mqdes, NULL);

// Note: Notification registration is one-shot.
// Must call mq_notify() again immediately after
// receiving the notification event.
